            { "Deposit", "deposit" },
        };
        return this.safeString(statuses, type, type);
    }

    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        //    {
        //         "id": "6500230339",
        //         "assetName": "XRP",
        //         "amount": "500",
        //         "type": "Deposit",
        //         "creationTime": "2020-07-27T07:52:08.640000Z",
        //         "status": "Complete",
        //         "description": "RIPPLE Deposit, XRP 500",
        //         "fee": "0",
        //         "lastUpdate": "2020-07-27T07:52:08.665000Z",
        //         "paymentDetail": {
        //             "txId": "lsjflsjdfljsd",
        //             "address": "kjasfkjsdf?dt=873874545"
        //         }
        //    }
        //
        //    {
        //         "id": "500985282",
        //         "assetName": "BTC",
        //         "amount": "0.42570126",
        //         "type": "Withdraw",
        //         "creationTime": "2017-07-29T12:49:03.931000Z",
        //         "status": "Complete",
        //         "description": "BTC withdraw from [nick-btcmarkets@snowmonkey.co.uk] to Address: 1B9DsnSYQ54VMqFHVJYdGoLMCYzFwrQzsj amount: 0.42570126 fee: 0.00000000",
        //         "fee": "0.0005",
        //         "lastUpdate": "2017-07-29T12:52:20.676000Z",
        //         "paymentDetail": {
        //             "txId": "fkjdsfjsfljsdfl",
        //             "address": "a;daddjas;djas"
        //         }
        //    }
        //
        //    {
        //         "id": "505102262",
        //         "assetName": "XRP",
        //         "amount": "979.836",
        //         "type": "Deposit",
        //         "creationTime": "2017-07-31T08:50:01.053000Z",
        //         "status": "Complete",
        //         "description": "Ripple Deposit, X 979.8360",
        //         "fee": "0",
        //         "lastUpdate": "2017-07-31T08:50:01.290000Z"
        //     }
        //
        Int64? timestamp = this.parse8601(this.safeString(transaction, "creationTime"));
        Int64? lastUpdate = this.parse8601(this.safeString(transaction, "lastUpdate"));
        string? type = this.parseTransactionType(this.safeStringLower(transaction, "type"));
        if (type == "withdraw")
        {
            type = "withdrawal";
        }
        IDictionary<string, object> cryptoPaymentDetail = this.safeDict(transaction, "paymentDetail", new Dictionary<string, object>() {});
        string? txid = this.safeString(cryptoPaymentDetail, "txId");
        object address = this.safeString(cryptoPaymentDetail, "address");
        object tag = null;
        if ((address != null))
        {
            List<object> addressParts = ((string)address).Split(new [] {"?dt="}, StringSplitOptions.None).ToList<object>();
            int numParts = addressParts.Count;
            if (numParts > 1)
            {
                address = (addressParts != null && 0 < addressParts.Count ? addressParts[0] : null);
                tag = (addressParts != null && 1 < addressParts.Count ? addressParts[1] : null);
            }
        }
        object addressTo = address;
        object tagTo = tag;
        object addressFrom = null;
        object tagFrom = null;
        string? fee = this.safeString(transaction, "fee");
        string? status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        string? currencyId = this.safeString(transaction, "assetName");
        string? code = this.safeCurrencyCode(currencyId);
        string? amount = this.safeString(transaction, "amount");
        if (((fee != null)) && (fee != ""))
        {
            amount = Precise.stringSub(amount, fee);
        }
        return new Dictionary<string, object>() {
            { "id", this.safeString(transaction, "id") },
            { "txid", txid },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", null },
            { "address", address },
            { "addressTo", addressTo },
            { "addressFrom", addressFrom },
            { "tag", tag },
            { "tagTo", tagTo },
            { "tagFrom", tagFrom },
            { "type", type },
            { "amount", this.parseNumber(amount) },
            { "currency", code },
            { "status", status },
            { "updated", lastUpdate },
            { "comment", this.safeString(transaction, "description") },
            { "internal", null },
            { "fee", new Dictionary<string, object>() {
                { "currency", code },
                { "cost", this.parseNumber(fee) },
                { "rate", null },
            } },
            { "info", transaction },
        };
    }

