    public override Dictionary<string, object> parseTicker(object ticker, object market = null)
    {
        //
        // fetchTicker
        //
        //     {
        //         "marketId":"BAT-AUD",
        //         "bestBid":"0.3751",
        //         "bestAsk":"0.377",
        //         "lastPrice":"0.3769",
        //         "volume24h":"56192.97613335",
        //         "volumeQte24h":"21179.13270465",
        //         "price24h":"0.0119",
        //         "pricePct24h":"3.26",
        //         "low24h":"0.3611",
        //         "high24h":"0.3799",
        //         "timestamp":"2020-08-09T18:28:23.280000Z"
        //     }
        //
        string? marketId = this.safeString(ticker, "marketId");
        market = this.safeMarket(marketId, market, "-");
        string? symbol = ((string)getValue(market, "symbol"));
        Int64? timestamp = this.parse8601(this.safeString(ticker, "timestamp"));
        string? last = this.safeString(ticker, "lastPrice");
        string? baseVolume = this.safeString(ticker, "volume24h");
        string? quoteVolume = this.safeString(ticker, "volumeQte24h");
        string? change = this.safeString(ticker, "price24h");
        string? percentage = this.safeString(ticker, "pricePct24h");
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", symbol },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", this.safeString(ticker, "high24h") },
            { "low", this.safeString(ticker, "low") },
            { "bid", this.safeString(ticker, "bestBid") },
            { "bidVolume", null },
            { "ask", this.safeString(ticker, "bestAsk") },
            { "askVolume", null },
            { "vwap", null },
            { "open", null },
            { "close", last },
            { "last", last },
            { "previousClose", null },
            { "change", change },
            { "percentage", percentage },
            { "average", null },
            { "baseVolume", baseVolume },
            { "quoteVolume", quoteVolume },
            { "info", ticker },
        }, market);
    }

