    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // public fetchTrades
        //
        //     {
        //         "id":"6191646611",
        //         "price":"539.98",
        //         "amount":"0.5",
        //         "timestamp":"2020-08-09T15:21:05.016000Z",
        //         "side":"Ask"
        //     }
        //
        // private fetchMyTrades
        //
        //     {
        //         "id": "36014819",
        //         "marketId": "XRP-AUD",
        //         "timestamp": "2019-06-25T16:01:02.977000Z",
        //         "price": "0.67",
        //         "amount": "1.50533262",
        //         "side": "Ask",
        //         "fee": "0.00857285",
        //         "orderId": "3648306",
        //         "liquidityType": "Taker",
        //         "clientOrderId": "48"
        //     }
        //
        Int64? timestamp = this.parse8601(this.safeString(trade, "timestamp"));
        string? marketId = this.safeString(trade, "marketId");
        market = this.safeMarket(marketId, market, "-");
        object feeCurrencyCode = null;
        if (isEqual(getValue(market, "quote"), "AUD"))
        {
            feeCurrencyCode = getValue(market, "quote");
        } else
        {
            feeCurrencyCode = getValue(market, "base");
        }
        string? side = this.safeString(trade, "side");
        if (side == "Bid")
        {
            side = "buy";
        } else if (side == "Ask")
        {
            side = "sell";
        }
        string? id = this.safeString(trade, "id");
        string? priceString = this.safeString(trade, "price");
        string? amountString = this.safeString(trade, "amount");
        string? orderId = this.safeString(trade, "orderId");
        Dictionary<string, object> fee = null;
        string? feeCostString = this.safeString(trade, "fee");
        if ((feeCostString != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", feeCostString },
                { "currency", feeCurrencyCode },
            };
        }
        string? takerOrMaker = this.safeStringLower(trade, "liquidityType");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", id },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "order", orderId },
            { "symbol", getValue(market, "symbol") },
            { "type", null },
            { "side", side },
            { "price", priceString },
            { "amount", amountString },
            { "cost", null },
            { "takerOrMaker", takerOrMaker },
            { "fee", fee },
        }, market);
    }

