    public override object calculateFee(string? symbol, string? type, string? side, double? amount, double? price, object takerOrMaker = null, object parameters = null)
    {
        /**
        * @method
        * @description calculates the presumptive fee that would be charged for an order
        * @param {string} symbol unified market symbol
        * @param {string} type not used by btcmarkets.calculateFee
        * @param {string} side not used by btcmarkets.calculateFee
        * @param {float} amount how much you want to trade, in units of the base currency on most exchanges, or number of contracts
        * @param {float} price the price for the order to be filled at, in units of the quote currency
        * @param {string} takerOrMaker 'taker' or 'maker'
        * @param {object} params
        * @returns {object} contains the rate, the percentage multiplied to the order amount to obtain the fee amount, and cost, the total value of the fee in units of the quote currency, for the order
        */
        takerOrMaker ??= "taker";
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> market = this.market(symbol);
        string? currency = null;
        string? cost = null;
        if ((((market.ContainsKey("quote") ? market["quote"] : null) as string) == "AUD"))
        {
            currency = this.safeString(market, "quote");
            string? amountString = this.numberToString(amount);
            string? priceString = this.numberToString(price);
            string? otherUnitsAmount = Precise.stringMul(amountString, priceString);
            cost = this.costToPrecision(symbol, otherUnitsAmount);
        } else
        {
            currency = this.safeString(market, "base");
            cost = this.amountToPrecision(symbol, amount);
        }
        object rate = this.safeValue(market, takerOrMaker);
        string? rateCost = Precise.stringMul(this.numberToString(rate), cost);
        string? feeCost = this.feeToPrecision(symbol, rateCost);
        if ((feeCost == null))
        {
            feeCost = "0";
        }
        return new Dictionary<string, object>() {
            { "type", takerOrMaker },
            { "currency", currency },
            { "rate", rate },
            { "cost", parseFloat(feeCost) },
        };
    }

    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "Accepted", "open" },
            { "Placed", "open" },
            { "Partially Matched", "open" },
            { "Fully Matched", "closed" },
            { "Cancelled", "canceled" },
            { "Partially Cancelled", "canceled" },
            { "Failed", "rejected" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Dictionary<string, object> parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // createOrder
        //
        //     {
        //         "orderId": "7524",
        //         "marketId": "BTC-AUD",
        //         "side": "Bid",
        //         "type": "Limit",
        //         "creationTime": "2019-08-30T11:08:21.956000Z",
        //         "price": "100.12",
        //         "amount": "1.034",
        //         "openAmount": "1.034",
        //         "status": "Accepted",
        //         "clientOrderId": "1234-5678",
        //         "timeInForce": "IOC",
        //         "postOnly": false,
        //         "selfTrade": "P",
        //         "triggerAmount": "105",
        //         "targetAmount": "1000"
        //     }
        //
        Int64? timestamp = this.parse8601(this.safeString(order, "creationTime"));
        string? marketId = this.safeString(order, "marketId");
        market = this.safeMarket(marketId, market, "-");
        string? side = this.safeString(order, "side");
        if (side == "Bid")
        {
            side = "buy";
        } else if (side == "Ask")
        {
            side = "sell";
        }
        string? type = this.safeStringLower(order, "type");
        string? price = this.safeString(order, "price");
        string? amount = this.safeString(order, "amount");
        string? remaining = this.safeString(order, "openAmount");
        string? status = this.parseOrderStatus(this.safeString(order, "status"));
        string? id = this.safeString(order, "orderId");
        string? clientOrderId = this.safeString(order, "clientOrderId");
        string? timeInForce = this.safeString(order, "timeInForce");
        bool? postOnly = this.safeBool(order, "postOnly");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", id },
            { "clientOrderId", clientOrderId },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "symbol", (market != null && market.ContainsKey("symbol") ? market["symbol"] : null) },
            { "type", type },
            { "timeInForce", timeInForce },
            { "postOnly", postOnly },
            { "side", side },
            { "price", price },
            { "triggerPrice", this.safeNumber(order, "triggerPrice") },
            { "cost", null },
            { "amount", amount },
            { "filled", null },
            { "remaining", remaining },
            { "average", null },
            { "status", status },
            { "trades", null },
            { "fee", null },
        }, market);
    }

    /**
     * @method
     * @name btcmarkets#fetchOrder
     * @description fetches information on an order made by the user
     * @see https://docs.btcmarkets.net/v3/#operation/getOrderById
     * @param {string} id the order id
     * @param {string} symbol not used by btcmarkets fetchOrder
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public async override Task<ccxt.Order> FetchOrder(string id, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", id },
        };
        Dictionary<string, object> response = await this.privateGetOrdersId(this.extend(request, parameters));
        return ccxt.BaseExchange.ToOrder(this.parseOrder(response));
    }

