    /**
     * @method
     * @name btcmarkets#withdraw
     * @description make a withdrawal
     * @see https://docs.btcmarkets.net/v3/#tag/Fund-Management-APIs/paths/~1v3~1withdrawals/post
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<ccxt.Transaction> Withdraw(string code, double amount, string address, string tag = null, object parameters = null)
    {
        string tagVar = tag;
        parameters ??= new Dictionary<string, object>();
        IList<object> tagparametersVariable = (IList<object>)this.handleWithdrawTagAndParams(tagVar, parameters);
        tagVar = (string)tagparametersVariable[0];
        parameters = tagparametersVariable[1];
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> currency = this.currency(code);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "assetName", (currency.ContainsKey("id") ? currency["id"] : null) },
            { "amount", this.currencyToPrecision(code, amount) },
        };
        if ((code != "AUD"))
        {
            this.checkAddress(address);
            request["toAddress"] = address;
        }
        if ((tagVar != null))
        {
            request["toAddress"] = ((address + "?dt=") + (tagVar));
        }
        Dictionary<string, object> response = await this.privatePostWithdrawals(this.extend(request, parameters));
        //
        //      {
        //          "id": "4126657",
        //          "assetName": "XRP",
        //          "amount": "25",
        //          "type": "Withdraw",
        //          "creationTime": "2019-09-04T00:04:10.973000Z",
        //          "status": "Pending Authorization",
        //          "description": "XRP withdraw from [me@test.com] to Address: abc amount: 25 fee: 0",
        //          "fee": "0",
        //          "lastUpdate": "2019-09-04T00:04:11.018000Z",
        //          "paymentDetail": {
        //              "address": "abc"
        //          }
        //      }
        //
        return ccxt.BaseExchange.ToTransaction(this.parseTransaction(response, currency));
    }

    public override Int64 nonce()
    {
        return this.milliseconds();
    }

    public override Dictionary<string, object> sign(object path, object api = null, string method = null, object parameters = null, object headers = null, object body = null)
    {
        api ??= "public";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        string request = ((("/" + this.version) + "/") + this.implodeParams(path, parameters));
        Dictionary<string, object> query = this.keysort(this.omit(parameters, this.extractParams(path)));
        if (isEqual(api, "private"))
        {
            this.checkRequiredCredentials();
            string nonce = this.nonce().ToString();
            byte[] secret = this.base64ToBinary(this.secret);
            object auth = ((method + request) + nonce);
            if (((method == "GET")) || ((method == "DELETE")))
            {
                if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
                {
                    request = request + ("?" + this.urlencode(query));
                }
            } else
            {
                body = this.json(query);
                auth = add(auth, body);
            }
            string signature = this.hmac(this.encode(auth), secret, sha512, "base64");
            headers = new Dictionary<string, object>() {
                { "Accept", "application/json" },
                { "Accept-Charset", "UTF-8" },
                { "Content-Type", "application/json" },
                { "BM-AUTH-APIKEY", this.apiKey },
                { "BM-AUTH-TIMESTAMP", nonce },
                { "BM-AUTH-SIGNATURE", signature },
            };
        } else if (isEqual(api, "public"))
        {
            if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
            {
                request = request + ("?" + this.urlencode(query));
            }
        }
        string? apiUrl = this.safeString((this.urls != null && ((IDictionary<string, object>)this.urls).ContainsKey("api") ? ((IDictionary<string, object>)this.urls)["api"] : null), api);
        if ((apiUrl == null))
        {
            throw new ExchangeError ((this.id + " sign() has no API URL for this endpoint")) ;
        }
        string url = (apiUrl + request);
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }

    public override object handleErrors(object code, string reason, string url, string method, object headers, object body, object response, Dictionary<string, object> requestHeaders, object requestBody)
    {
        if ((response == null))
        {
            return null;  // fallback to default error handler
        }
        //
        //     {"code":"UnAuthorized","message":"invalid access token"}
        //     {"code":"MarketNotFound","message":"invalid marketId"}
        //
        string? errorCode = this.safeString(response, "code");
        string? message = this.safeString(response, "message");
        if ((errorCode != null))
        {
            string feedback = ((this.id + " ") + (body));
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), message, feedback);
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), errorCode, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("broad") ? ((IDictionary<string, object>)this.exceptions)["broad"] : null), message, feedback);
            throw new ExchangeError (feedback) ;
        }
        return null;
    }
